+package com.example.customers.domain;
+
+import java.io.Serializable;
+import java.text.Normalizer;
+import java.util.List;
+import java.util.Locale;
+import java.util.Set;
+import java.util.regex.Pattern;
+
+/** The same matching rules are used for both page and count queries. */
+public record CustomerFilter(String name, Set<CustomerStatus> statuses) implements Serializable {
+    public static final CustomerFilter EMPTY = new CustomerFilter("", Set.of());
+    private static final Pattern MARKS = Pattern.compile("\\p{M}+");
+    private static final Pattern WHITESPACE = Pattern.compile("\\s+", Pattern.UNICODE_CHARACTER_CLASS);
+
+    public CustomerFilter {
+        name = name == null ? "" : name;
+        statuses = Set.copyOf(statuses);
+    }
+
+    public List<String> terms() {
+        return WHITESPACE.splitAsStream(normalize(name))
+                .filter(term -> !term.isEmpty()).toList();
+    }
+
+    public boolean matches(Customer customer, List<String> terms) {
+        if (!statuses.isEmpty() && !statuses.contains(customer.status())) {
+            return false;
+        }
+        String first = normalize(customer.firstName());
+        String last = normalize(customer.lastName());
+        return terms.stream().allMatch(term -> first.contains(term) || last.contains(term));
+    }
+
+    private static String normalize(String text) {
+        return MARKS.matcher(Normalizer.normalize(text, Normalizer.Form.NFD))
+                .replaceAll("").toLowerCase(Locale.ROOT);
+    }
+}
